import React, { useState, useEffect } from 'react';
import { Col, Row, Form } from 'react-bootstrap';
import { Link, useNavigate } from 'react-router-dom';
import CompanyDetails from '../../components/Atom/CompanyDetails';
import noProfile from '../../assets/images/noprofile_images.jpg';
import moment from 'moment';

const placeholders = [
    "Who’s the staff member you're thinking about? Type their name or ID.",
    "Need a staff name? Just start typing and we’ll help you find it.",
    "Looking up a staff ID or name? Enter it here to begin your search.",
    "Ready to discover details about your staff? Start by typing their info.",
    "Want to find your staff in seconds? Just enter their name or ID below."
];

const Index = () => {
    const [state] = useState({
        "genderId": 0,
        "staffExperiance": [
            {
                "title": "Knock the globe technology",
                "remarks": "Best Employee",
                "dateOfJoining": "2025-08-30",
                "dateOfReleving": "2025-08-30",
                "relevingReason": "Family issue",
                "rating": "10 out of 10",

                "roles": [{
                    "fromDate": "2023-08-09",
                    "toDate": "2023-11-30",
                    "positionName": "Frontend Developer Intern"
                },
                {
                    "fromDate": "2023-12-01",
                    "toDate": "2024-08-09",
                    "positionName": "Frontend Developer"
                },
                {
                    "fromDate": "2024-08-09",
                    "toDate": "2025-07-24",
                    "positionName": "Full stack developer"
                }]
            },
            {
                "title": "Zoho",
                "remarks": "Best Employee",
                "dateOfJoining": "2025-08-30",
                "relevingReason": "Salary issue",
                "rating": "10 out of 10",
                "roles": [{
                    "fromDate": "2023-08-09",
                    "toDate": "2023-11-30",
                    "positionName": "Frontend Developer Intern"
                },
                {
                    "fromDate": "2023-12-01",
                    "toDate": "2024-08-09",
                    "positionName": "Frontend Developer"
                },
                {
                    "fromDate": "2024-08-09",
                    "toDate": "2025-07-24",
                    "positionName": "Full stack developer"
                }]
            },
        ],
        "bloodGroupdId": 6,
        "employeeName": "surya",
        "fatherName": "Palanisamy",
        "mobileNumber": "9968574130",
        "emailId": "surya@gmail.com",
        "qualification": "BCA",
        "addressI": "53, west madavilagam",
        "addressII": "karur",
        "profileImg": [
            {}
        ],
        "aadharNumber": "Aadhar987456321034",
        "aadharImg": [
            {}
        ],
        "panCardNumber": "Pan47893310",
        "panCardImg": [
            {}
        ],
        "drivingLicenseNumber": "Driv54757866",
        "drivingLicenseImg": [
            {}
        ],
        "fromDate": "2024-08-09",
        "toDate": "2025-07-24",
        "positionName": "Full stack developer",
        "dateOfReleving": "2025-08-30",
        "relevingReason": "Salary issue",
        "rating": "10 out of 10",
    });
    const navigate = useNavigate();
    const [searchText, setSearchText] = useState('');
    const [showError, setShowError] = useState(false);
    const [placeholderIndex, setPlaceholderIndex] = useState(0);
    const [displayedPlaceholder, setDisplayedPlaceholder] = useState('');
    const [charIndex, setCharIndex] = useState(0);
    const [showResultPanel, setShowResultPanel] = useState(false);
    const [isLoadingResultPanel, setIsLoadingResultPanel] = useState(false);

    useEffect(() => {
        let typingInterval;
        if (charIndex < placeholders[placeholderIndex].length) {
            typingInterval = setTimeout(() => {
                setDisplayedPlaceholder((prev) => prev + placeholders[placeholderIndex][charIndex]);
                setCharIndex(charIndex + 1);
            }, 50);
        } else {
            typingInterval = setTimeout(() => {
                setDisplayedPlaceholder('');
                setCharIndex(0);
                setPlaceholderIndex((prev) => (prev + 1) % placeholders.length);
            }, 2000);
        }
        return () => clearTimeout(typingInterval);
    }, [charIndex, placeholderIndex]);

    useEffect(() => {
        if (isLoadingResultPanel) {
            setTimeout(() => {
                setIsLoadingResultPanel(false);
            }, 1500);
        }
    }, [isLoadingResultPanel]);

    useEffect(() => {
        document.body.style.overflow = showResultPanel ? 'hidden' : 'auto';
    }, [showResultPanel]);

    const handleSearch = () => {
        if (searchText.trim()) {
            setShowError(false);
            setIsLoadingResultPanel(true);
            setShowResultPanel(true);
        } else {
            setShowError(true);
        }
    };

    return (
        <div className="position-relative mt-5">
            <Row className="g-0">
                <Col xs={showResultPanel ? 5 : 12}>
                    <CompanyDetails
                        fontSize="16px"
                        imgSize="250px"
                        borderBottom={false}
                        classStyle={`d-flex flex-column align-items-center justify-content-center ${showResultPanel ? 'align-items-start ps-4' : ''}`}
                    />
                    <div className="mt-4 position-relative search-wrapper" style={{ maxWidth: 700, margin: '0 auto' }}>
                        <Form.Control
                            className={`highlight-placeholder ${showError ? 'input-error' : ''}`}
                            type="text"
                            value={searchText}
                            onChange={(e) => {
                                setSearchText(e.target.value);
                                if (e.target.value.trim()) setShowError(false);
                            }}
                            onBlur={() => {
                                if (!searchText.trim()) setShowError(true);
                            }}
                            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                            placeholder={!searchText ? displayedPlaceholder : ''}
                            style={{
                                height: '60px',
                                borderRadius: '15px',
                                paddingRight: '40px',
                                paddingLeft: '15px',
                                fontSize: '18px',
                                width: '100%',
                            }}
                        />
                        <i
                            className="fe-search"
                            onClick={handleSearch}
                            style={{
                                position: 'absolute',
                                right: '15px',
                                top: '50%',
                                transform: 'translateY(-50%)',
                                cursor: 'pointer',
                                fontSize: '20px',
                                color: '#072e52f9',
                            }}
                        />
                    </div>
                    <div className='d-flex justify-content-center mt-4 flex-wrap gap-3'>
                        <Link to="/e-mark/register-staff" className='text-center text-decoration-none px-3' style={{ color: "#072e52d8", fontWeight: "bold", fontSize: "15px" }}>
                            <i className="fe-user fw-bold"></i> register a staff member
                        </Link>
                        <Link to="/e-mark/enterprise-information" className='text-center text-decoration-none px-3' style={{ color: "#072e52d8", fontWeight: "bold", fontSize: "15px" }}>
                            <i className="fe-info fw-bold"></i> enterprise information
                        </Link>
                    </div>
                </Col>
            </Row>
            <div className={`staff-panel ${showResultPanel ? 'open' : ''}`}>
                <div className="p-4">
                    <div className="d-flex justify-content-end">
                        <div
                            title="Close"
                            onClick={() => setShowResultPanel(false)}
                            style={{
                                cursor: "pointer",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                backgroundColor: "#f8d7da",
                                color: "#721c24",
                                borderRadius: "50%",
                                width: "35px",
                                height: "35px",
                                transition: "background-color 0.3s ease, transform 0.2s ease",
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.backgroundColor = "#f5c6cb";
                                e.currentTarget.style.transform = "scale(1.05)";
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.backgroundColor = "#f8d7da";
                                e.currentTarget.style.transform = "scale(1)";
                            }}
                        >
                            <i className="fe-x fw-bold" style={{ fontSize: "18px" }}></i>
                        </div>
                    </div>
                    {isLoadingResultPanel ? (
                        <div className="px-4 pt-3">
                            <div className="skeleton-avatar mb-4"></div>
                            <div className="skeleton-line mb-2" style={{ width: '40%' }}></div>
                            <div className="skeleton-line mb-2" style={{ width: '60%' }}></div>
                            <div className="skeleton-line mb-2" style={{ width: '50%' }}></div>
                            <div className="d-flex gap-3 mt-3">
                                <div className="skeleton-button" style={{ width: 100 }}></div>
                                <div className="skeleton-button" style={{ width: 120 }}></div>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center mt-3 animate-fade-in px-3 px-md-5">
                            <img
                                src={state.profileImg?.[0]?.url || noProfile}
                                alt="Profile"
                                style={{
                                    width: 150,
                                    height: 150,
                                    borderRadius: '50%',
                                    objectFit: 'cover',
                                    marginBottom: 20,
                                    animation: 'zoomIn 0.5s ease',
                                    border: '2px solid #ccc'
                                }}
                            />
                            <h4 className="text-capitalize fw-bold">{state.employeeName}</h4>
                            <div className='d-flex flex-column align-items-center'>
                                <table style={{ marginLeft: "60px" }}>
                                    <tr>
                                        <th className='text-start' style={{ width: "34%" }}>Father</th>
                                        <td className='text-start'>: {state.fatherName}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>Mobile No</th>
                                        <td className='text-start'>: {state.mobileNumber}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>Email Id</th>
                                        <td className='text-start'>: {state.emailId}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>Qualification</th>
                                        <td className='text-start'>: {state.qualification}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>Address</th>
                                        <td className='text-start'>: {state.addressI}, {state.addressII}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>Aadhar No</th>
                                        <td className='text-start'>: {state.aadharNumber}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>Pan Card</th>
                                        <td className='text-start'>: {state.panCardNumber}</td>
                                    </tr>
                                    <tr>
                                        <th className='text-start'>License No</th>
                                        <td className='text-start'>: {state.drivingLicenseNumber}</td>
                                    </tr>
                                </table>
                            </div>
                            <div className="border rounded p-3 bg-light mt-4">
                                <h4 className="fw-bold mb-3">Work Experience</h4>
                                {state.staffExperiance?.map((comp, idx) => (
                                    <div className='mb-3'>
                                        <h4 className='text-start'>{comp?.title}
                                            <br />
                                            <div className='text-start' style={{ marginTop: "6px", fontSize: "15px" }}>{`(${moment(comp?.dateOfJoining || null).format("DD-MM-YYYY")} - ${comp?.dateOfReleving ? moment(comp?.dateOfReleving || null).format("DD-MM-YYYY") : "Present"})`}</div>
                                        </h4>
                                        {comp?.roles?.map((exp, idx) => (
                                            <div key={idx} className="d-flex justify-content-between mb-1">
                                                <div><strong>{exp.positionName}</strong></div>
                                                <div className="text-muted" style={{ fontSize: '14px' }}>
                                                    {moment(exp.fromDate).format("DD-MM-YYYY")} to {moment(exp.toDate).format("DD-MM-YYYY")}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ))}
                            </div>
                            <div className="d-flex justify-content-center gap-2 mt-4 flex-wrap">

                                <Link to="/e-mark/biodata" state={state} style={{borderBottom:"1px solid #71b6f9"}}>More Details</Link>
                                {/* <button className="btn btn-outline-secondary">Download</button> */}
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {showResultPanel && <div className="offcanvas-backdrop" onClick={() => setShowResultPanel(false)} />}

            <style>{`
                .highlight-placeholder::placeholder {
                    color: #072e5280;
                    font-weight: bold;
                    font-size: 18px;
                    opacity: 1;
                    transition: all 0.3s ease;
                    animation: fadeInSlide 1s ease-in-out;
                }

                @keyframes fadeInSlide {
                    0% { opacity: 0; transform: translateY(10px); }
                    100% { opacity: 1; transform: translateY(0); }
                }

                .highlight-placeholder:focus {
                    border: 2px solid #072e5280 !important;
                    box-shadow: none;
                }

                .input-error {
                    border: 2px solid #db131380 !important;
                }

                .staff-panel {
                    position: fixed;
                    top: 0;
                    right: 0;
                    transform: translateX(100%);
                    width: 49%;
                    height: 100%;
                    background-color: #f8f9fa;
                    border-left: 2px solid #dee2e6;
                    border-radius: 15px 0 0 15px;
                    box-shadow: -3px 0 10px rgba(0,0,0,0.1);
                    transition: transform 0.4s ease;
                    z-index: 1051;
                    overflow-y: scroll;
                }

                .staff-panel::-webkit-scrollbar{
                display:none;
                }

                .staff-panel.open {
                    transform: translateX(0%);
                }

                .offcanvas-backdrop {
                    position: fixed;
                    top: 0;
                    left: 0;
                    width: 100vw;
                    height: 100vh;
                    background-color: rgba(0, 0, 0, 0.3);
                    z-index: 1050;
                }

                .skeleton-avatar,
                .skeleton-line,
                .skeleton-button {
                    background: linear-gradient(90deg, #eee 25%, #f5f5f5 50%, #eee 75%);
                    background-size: 200% 100%;
                    animation: shimmer 1.5s infinite;
                }

                .skeleton-avatar {
                    width: 150px;
                    height: 150px;
                    border-radius: 50%;
                    margin: 0 auto;
                }

                .skeleton-line {
                    height: 20px;
                    border-radius: 4px;
                }

                .skeleton-button {
                    height: 36px;
                    border-radius: 6px;
                }

                @keyframes shimmer {
                    0% { background-position: 200% 0; }
                    100% { background-position: -200% 0; }
                }

                .animate-fade-in {
                    animation: fadeIn 0.3s ease-in-out;
                }

                @keyframes fadeIn {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }

                @keyframes zoomIn {
                    from {
                        opacity: 0;
                        transform: scale(0.8);
                    }
                    to {
                        opacity: 1;
                        transform: scale(1);
                    }
                }

                @media (max-width: 768px) {
                    .staff-panel {
                        width: 100%;
                        top: auto;
                        bottom: 0;
                        right: 0;
                        height: 80%;
                        border-radius: 15px 15px 0 0;
                        transform: translateY(100%);
                        transition: transform 0.4s ease;
                    }

                    .staff-panel.open {
                        transform: translateY(0%);
                    }
                }
            `}</style>
        </div >
    );
};

export default Index;
